// Extract order info from email
const email = $input.first().json;
const body = email.text || email.snippet || email.payload?.body?.data || '';
const subject = email.subject || '';
const from = email.from || '';

// Detect retailer from sender/subject
function detectRetailer(from, subject) {
  const s = (from + ' ' + subject).toLowerCase();
  if (s.includes('amazon')) return 'Amazon';
  if (s.includes('target')) return 'Target';
  if (s.includes('bestbuy') || s.includes('best buy')) return 'Best Buy';
  if (s.includes('crateandbarrel') || s.includes('crate & barrel')) return 'Crate & Barrel';
  if (s.includes('williams') && s.includes('sonoma')) return 'Williams Sonoma';
  return 'Unknown';
}

// Extract tracking number
function extractTracking(text) {
  const patterns = [
    /tracking(?:\s+number)?:?\s*([A-Z0-9]{10,30})/i,
    /(?:UPS|USPS|FedEx|DHL)[^A-Z0-9]*([A-Z0-9]{10,30})/i,
    /order\s+(?:number|#|id):?\s*([A-Z0-9\-]{6,30})/i
  ];
  for (const p of patterns) {
    const m = (text || '').match(p);
    if (m) return m[1];
  }
  return null;
}

// Extract item name from subject
function extractItem(subject) {
  return subject
    .replace(/^(your\s+)?(order|purchase|confirmation)[:\s]*/i, '')
    .replace(/has\s+(shipped|been\s+delivered).*/i, '')
    .trim()
    .substring(0, 150);
}

const retailer = detectRetailer(from, subject);
const tracking = extractTracking(body);
const itemHint = extractItem(subject);

// Try to guess buyer from from-address
let buyer = '';
const emailMatch = from.match(/([^<@]+)/);
if (emailMatch) buyer = emailMatch[1].trim().replace(/"/g, '');

return [{
  json: {
    emailId: email.id,
    subject,
    from,
    retailer,
    tracking,
    itemHint,
    buyer,
    rawBody: body.substring(0, 2000)
  }
}];

// Match the best ClickUp task to this order
const orderInfo = $node['Extract Order Info'].first().json;
const searchResult = $input.first().json;
const tasks = searchResult.tasks || [];

if (tasks.length === 0) {
  return [{ json: { noMatch: true, ...orderInfo } }];
}

// Pick the first result (best match from ClickUp search)
const task = tasks[0];

const THANK_YOU_DRAFTED_UUID = 'e97f1e8b-2b78-406e-b907-ac6ac41fc22d'; // Drafted by AI
const DELIVERY_ORDERED_UUID = '7c547f2e-56da-49ca-bda1-97469d406e66'; // Ordered

const thankYouDraft = `Dear ${orderInfo.buyer || 'Gift Giver'},

Thank you so much for the thoughtful gift! We truly appreciate your generosity and kindness.

With love,
Zuha & [Fiancé]`;

return [{
  json: {
    taskId: task.id,
    taskName: task.name,
    orderInfo,
    newStatus: 'PURCHASED / GIFTED',
    deliveryStatusUuid: DELIVERY_ORDERED_UUID,
    thankYouUuid: THANK_YOU_DRAFTED_UUID,
    thankYouDraft,
    customFields: [
      { id: '62e11a44-da30-4b7b-801e-8b04fa9f4e06', value: orderInfo.buyer },
      { id: '669c6837-8afb-452e-9ad4-4e3446613b5d', value: orderInfo.tracking || '' },
      { id: '550e5a43-2bce-422e-91dc-8a67e5a3fc07', value: DELIVERY_ORDERED_UUID },
      { id: 'f9883690-3b1a-4d34-bef1-32973bc00d74', value: THANK_YOU_DRAFTED_UUID }
    ].filter(f => f.value)
  }
}];
